-- =====================================================================
-- BogoTickets · 04 · Datos de prueba
-- Ejecutar después de 03_vistas.sql. Los triggers del script 02 validan
-- cada fila mientras se carga. Valores en pesos colombianos (COP).
-- Los escenarios, artistas, equipos y obras son reales; las fechas,
-- precios, edades mínimas, clientes y ventas son datos de prueba.
--
-- Cuentas para entrar a la aplicación (las contraseñas se guardan con BCrypt):
--   Cliente        laura.rodriguez92@gmail.com   Cliente2026*  (todos los clientes usan esta clave)
--   Cliente menor  sara.medina@gmail.com         Cliente2026*  (16 años: prueba de RN-25)
--   Administrador  admin@bogotickets.co          Admin2026*
--   Analista       analista@bogotickets.co       Analista2026*
--
-- Registros sin relación a propósito: el escenario 18 no tiene eventos, el
-- tipo 10 (Circo) no tiene eventos, el evento 22 no tiene ventas y algunos
-- clientes no han comprado.
-- =====================================================================

